"""Board-side selection request/ack backend (HF-05).

Only three actions are accepted: ``select``, ``release`` and
``capture_baseline``. Every request must carry ``schema_version=1`` and is bound
to a ``request_id``, the session, the source ``time_epoch``, a candidate
``snapshot_id`` and a ``selection_version``; a bare pixel box is never accepted
as a metric position. The backend is the single authority on whether a selection
succeeded.

Freshness/protocol rules (HF04-06 R2): registration and request receive times
must be finite in one monotonic domain; a future snapshot (negative age), an
expired snapshot, a cross-epoch request, an unknown schema, a non-integer
version and a mismatched calibration are all rejected *before* any state
change. The calibration version is derived from the board-side snapshot, never
trusted from the client. A new/cleared target invalidates any previous ready
baseline. Idempotency is preserved: a repeated ``request_id`` with identical
content returns the original ack and is not executed twice; the same id with
different content is rejected.
"""

import json
import math
from collections import deque

try:  # pragma: no cover - import shim
    from core.baseline import StanceBaselineCollector
except ImportError:  # pragma: no cover
    from baseline import StanceBaselineCollector

ACTIONS = ("select", "release", "capture_baseline")
ACK_KIND = "selection_ack"
SCHEMA_VERSION = 1

DEFAULT_SETTINGS = {
    "snapshot_ttl_s": 2.0,
    "request_cache_size": 64,
    "snapshot_cache_size": 16,
}

REASON_UNKNOWN = "unknown_action"
REASON_MISSING_FIELD = "missing_field"
REASON_SESSION_MISMATCH = "session_mismatch"
REASON_CONFLICT = "request_id_conflict"
REASON_NONMONOTONIC = "nonmonotonic_time"
REASON_INVALID_RECEIVE = "invalid_receive_time"
REASON_INVALID_EPOCH = "invalid_time_epoch"
REASON_UNSUPPORTED_SCHEMA = "unsupported_schema_version"
REASON_UNKNOWN_SNAPSHOT = "unknown_snapshot"
REASON_STALE_SNAPSHOT = "stale_snapshot"
REASON_FUTURE_SNAPSHOT = "snapshot_in_future"
REASON_EPOCH_MISMATCH = "epoch_mismatch"
REASON_UNKNOWN_CANDIDATE = "unknown_candidate"
REASON_INSUFFICIENT_QUALITY = "insufficient_candidate_quality"
REASON_STALE_VERSION = "stale_selection_version"
REASON_INVALID_VERSION = "invalid_selection_version"
REASON_CALIBRATION_MISMATCH = "calibration_mismatch"
REASON_NOT_LOCKED = "target_not_locked"
REASON_TRACK_MISMATCH = "track_mismatch"


def resolve_settings(settings=None):
    resolved = dict(DEFAULT_SETTINGS)
    for key, value in (settings or {}).items():
        if key not in resolved:
            raise ValueError("unknown selection setting: " + str(key))
        resolved[key] = value
    if float(resolved["snapshot_ttl_s"]) <= 0.0:
        raise ValueError("snapshot_ttl_s must be positive")
    resolved["snapshot_ttl_s"] = float(resolved["snapshot_ttl_s"])
    resolved["request_cache_size"] = int(resolved["request_cache_size"])
    resolved["snapshot_cache_size"] = int(resolved["snapshot_cache_size"])
    if resolved["request_cache_size"] <= 0 or resolved["snapshot_cache_size"] <= 0:
        raise ValueError("cache sizes must be positive")
    return resolved


def _finite(value):
    if value is None:
        return None
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if math.isfinite(number) else None


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


class SelectionBackend:
    def __init__(self, session_id, tracker, baseline=None, settings=None):
        self.session_id = session_id
        self.tracker = tracker
        self.baseline = baseline if baseline is not None else StanceBaselineCollector(session_id)
        self.settings = resolve_settings(settings)
        self.time_epoch = tracker.time_epoch if tracker.time_epoch is not None else 0
        self._snapshots = {}
        self._snapshot_order = deque()
        self._requests = {}
        self._request_order = deque()
        self._last_receive_s = None
        self._track_counter = 0

    def set_epoch(self, time_epoch):
        self.time_epoch = int(time_epoch)
        self.tracker.note_epoch(self.time_epoch)
        self.baseline.invalidate("time_epoch_changed")

    def register_snapshot(self, snapshot, receive_s):
        snapshot_id = snapshot.get("snapshot_id")
        if not snapshot_id:
            raise ValueError("snapshot needs a snapshot_id")
        receive = _finite(receive_s)
        if receive is None:
            raise ValueError("snapshot receive time must be finite")
        self._snapshots[snapshot_id] = {"receive_s": receive,
                                        "time_epoch": snapshot.get("time_epoch"),
                                        "snapshot": snapshot}
        self._snapshot_order.append(snapshot_id)
        while len(self._snapshot_order) > self.settings["snapshot_cache_size"]:
            self._snapshots.pop(self._snapshot_order.popleft(), None)

    def _ack(self, request, accepted, reason, *, track_id=None, selection_version=None,
             candidate_id=None, baseline=None, idempotent_replay=False):
        return {
            "kind": ACK_KIND,
            "schema_version": SCHEMA_VERSION,
            "request_id": request.get("request_id"),
            "action": request.get("action"),
            "session_id": self.session_id,
            "time_epoch": self.time_epoch,
            "accepted": bool(accepted),
            "reason": reason,
            "track_id": track_id,
            "candidate_id": candidate_id,
            "selection_version": selection_version,
            "baseline": baseline,
            "idempotent_replay": bool(idempotent_replay),
        }

    def _remember(self, request, ack):
        request_id = request["request_id"]
        content = json.dumps(request, sort_keys=True)
        self._requests[request_id] = {"content": content, "ack": ack}
        self._request_order.append(request_id)
        while len(self._request_order) > self.settings["request_cache_size"]:
            self._requests.pop(self._request_order.popleft(), None)

    def handle(self, request, receive_s):
        if not isinstance(request, dict):
            raise ValueError("request must be an object")
        request_id = request.get("request_id")
        if not isinstance(request_id, str) or not request_id:
            return self._ack(request, False, REASON_MISSING_FIELD)

        content = json.dumps(request, sort_keys=True)
        cached = self._requests.get(request_id)
        if cached is not None:
            if cached["content"] == content:
                replay = dict(cached["ack"])
                replay["idempotent_replay"] = True
                return replay
            return self._ack(request, False, REASON_CONFLICT)

        receive = _finite(receive_s)
        if receive is None:
            return self._ack(request, False, REASON_INVALID_RECEIVE)
        action = request.get("action")
        if action not in ACTIONS:
            return self._ack(request, False, REASON_UNKNOWN)
        if request.get("session_id") != self.session_id:
            return self._ack(request, False, REASON_SESSION_MISMATCH)
        if not _is_int(request.get("schema_version")) \
                or request.get("schema_version") != SCHEMA_VERSION:
            return self._ack(request, False, REASON_UNSUPPORTED_SCHEMA)
        epoch = request.get("time_epoch")
        if not _is_int(epoch):
            return self._ack(request, False, REASON_INVALID_EPOCH)
        if epoch != self.time_epoch:
            return self._ack(request, False, REASON_EPOCH_MISMATCH)
        if self._last_receive_s is not None and receive < self._last_receive_s:
            return self._ack(request, False, REASON_NONMONOTONIC)
        self._last_receive_s = receive

        if action == "select":
            ack = self._select(request, receive)
        elif action == "release":
            ack = self._release(request)
        else:
            ack = self._capture_baseline(request, receive)
        self._remember(request, ack)
        return ack

    def _expected_version(self, request):
        version = request.get("selection_version")
        if not _is_int(version):
            return None, self._ack(request, False, REASON_INVALID_VERSION)
        current = int(self.tracker.selection_version)
        if version < current:
            return None, self._ack(request, False, REASON_STALE_VERSION)
        if version > current:
            return None, self._ack(request, False, REASON_INVALID_VERSION)
        return current, None

    def _snapshot_entry(self, request, receive_s):
        snapshot_id = request.get("snapshot_id")
        if not snapshot_id:
            return None, self._ack(request, False, REASON_MISSING_FIELD)
        entry = self._snapshots.get(snapshot_id)
        if entry is None:
            return None, self._ack(request, False, REASON_UNKNOWN_SNAPSHOT)
        age = receive_s - entry["receive_s"]
        if age < 0.0:
            return None, self._ack(request, False, REASON_FUTURE_SNAPSHOT)
        if age > self.settings["snapshot_ttl_s"]:
            return None, self._ack(request, False, REASON_STALE_SNAPSHOT)
        if entry["time_epoch"] != self.time_epoch:
            return None, self._ack(request, False, REASON_EPOCH_MISMATCH)
        return entry, None

    def _lookup_candidate(self, request, receive_s):
        entry, error = self._snapshot_entry(request, receive_s)
        if error is not None:
            return None, None, error
        candidate_id = request.get("candidate_id")
        if not candidate_id:
            return None, None, self._ack(request, False, REASON_MISSING_FIELD)
        for candidate in entry["snapshot"].get("candidates", []):
            if candidate.get("candidate_id") == candidate_id:
                return entry, candidate, None
        return None, None, self._ack(request, False, REASON_UNKNOWN_CANDIDATE)

    @staticmethod
    def _snapshot_calibration(entry):
        calibration = (entry["snapshot"].get("calibration") or {})
        return calibration.get("calibration_id")

    def _select(self, request, receive_s):
        current, error = self._expected_version(request)
        if error is not None:
            return error
        entry, candidate, error = self._lookup_candidate(request, receive_s)
        if error is not None:
            return error
        quality = candidate.get("quality") or {}
        if not quality.get("sufficient_points", False):
            return self._ack(request, False, REASON_INSUFFICIENT_QUALITY)
        board_calibration = self._snapshot_calibration(entry)
        requested_calibration = request.get("calibration_version")
        if requested_calibration is not None and requested_calibration != board_calibration:
            return self._ack(request, False, REASON_CALIBRATION_MISMATCH)
        self.baseline.invalidate("target_changed")
        source_stamp_s = (entry["snapshot"].get("source") or {}).get("source_stamp_s")
        self._track_counter += 1
        track_id = "t{:04d}".format(self._track_counter)
        new_version = current + 1
        self.tracker.select(track_id, self.time_epoch, candidate=candidate,
                            calibration_version=board_calibration,
                            selection_version=new_version,
                            source_stamp_s=source_stamp_s, receive_s=receive_s)
        return self._ack(request, True, None, track_id=track_id,
                         selection_version=new_version,
                         candidate_id=candidate.get("candidate_id"))

    def _release(self, request):
        current, error = self._expected_version(request)
        if error is not None:
            return error
        requested_track = request.get("track_id")
        if requested_track is not None and requested_track != self.tracker.track_id:
            return self._ack(request, False, REASON_TRACK_MISMATCH,
                             selection_version=current)
        self.tracker.release()
        self.tracker.selection_version = current + 1
        self.baseline.invalidate("target_released")
        return self._ack(request, True, None, selection_version=current + 1,
                         track_id=None)

    def _capture_baseline(self, request, receive_s):
        current, error = self._expected_version(request)
        if error is not None:
            return error
        if self.tracker.track_status != "locked":
            return self._ack(request, False, REASON_NOT_LOCKED,
                             selection_version=current)
        requested_track = request.get("track_id")
        if requested_track is not None and requested_track != self.tracker.track_id:
            return self._ack(request, False, REASON_TRACK_MISMATCH,
                             selection_version=current)
        start_source_s = self.tracker.last_measured_source()
        if start_source_s is None:
            start_source_s = receive_s
        self.baseline.start(self.tracker.track_id, self.tracker.calibration_version,
                            start_source_s=start_source_s,
                            operator_confirmed=bool(request.get("operator_confirmed")),
                            time_epoch=self.time_epoch,
                            selection_version=current,
                            action_generation=self.tracker.action_generation)
        return self._ack(request, True, None, track_id=self.tracker.track_id,
                         selection_version=current,
                         baseline=self.baseline.snapshot())

#!/usr/bin/env python3
"""Publish strict-JSON health for the point cloud, auxiliary IMU and device status. Read-only."""

import argparse
import json
import math
import os
import sys
import tempfile
import threading
import time

import numpy as np

SCHEMA_VERSION = 1
HEALTH_KIND = "health"
SOURCE_TIME_DOMAIN = "device_stamp_s_unanchored"
QUATERNION_UNIT_TOLERANCE = 1e-3
FLOAT32_DATATYPE = 7
FLOAT64_DATATYPE = 8
STAMP_STATUSES = ("none", "first", "ok", "repeated", "regressed", "forward_jump", "invalid")


def finite_or_none(value):
    if value is None:
        return None
    number = float(value)
    return number if math.isfinite(number) else None


def dumps_strict(payload):
    return json.dumps(payload, allow_nan=False)


def save_json(path, data):
    directory = os.path.abspath(os.path.dirname(path) or ".")
    os.makedirs(directory, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=directory,
                                         prefix=".human-fall-", suffix=".json",
                                         delete=False) as output:
            temporary = output.name
            json.dump(data, output, indent=2, ensure_ascii=False, allow_nan=False)
            output.write("\n")
        os.replace(temporary, path)
    finally:
        if temporary and os.path.exists(temporary):
            os.unlink(temporary)


def stamp_pair(header):
    return (int(header.secs), int(header.nsecs))


def valid_stamp(stamp):
    if stamp is None or len(stamp) != 2:
        return False
    secs, nsecs = int(stamp[0]), int(stamp[1])
    if secs < 0 or nsecs < 0 or nsecs >= 1000000000:
        return False
    return (secs, nsecs) != (0, 0)


def stamp_seconds(stamp):
    if not valid_stamp(stamp):
        return None
    return int(stamp[0]) + int(stamp[1]) / 1e9


def raw_stamp(stamp):
    """Raw integer sec/nsec of the current frame, kept even when the stamp is invalid."""
    if stamp is None or len(stamp) != 2:
        return None, None
    try:
        return int(stamp[0]), int(stamp[1])
    except (TypeError, ValueError):
        return None, None


def check_stamp(prefix, previous, current, max_forward_jump_s):
    """Classify a new source stamp. Returns (status, reason, discontinuity)."""
    if not valid_stamp(current):
        return "invalid", prefix + "_stamp_invalid", False
    if previous is None:
        return "first", None, False
    current_s = stamp_seconds(current)
    previous_s = stamp_seconds(previous)
    if current_s < previous_s:
        return "regressed", prefix + "_stamp_regressed", True
    if current_s == previous_s:
        return "repeated", prefix + "_stamp_repeated", True
    if current_s - previous_s > float(max_forward_jump_s):
        return "forward_jump", prefix + "_stamp_forward_jump", True
    return "ok", None, False


def orientation_covariance_flags(covariance):
    """Return (all_zero, not_provided) for the ROS Imu 9-element covariance array.

    All nine entries zero only mark the covariance as unknown; a first entry of -1
    means the orientation estimate is not provided and must be ignored.
    """
    values = [float(value) for value in covariance] if covariance is not None else []
    all_zero = len(values) == 9 and all(value == 0.0 for value in values)
    not_provided = bool(values) and values[0] == -1.0
    return all_zero, not_provided


def quaternion_report(quaternion):
    """Return (usable, reason). All-zero, non-finite and non-unit quaternions are unusable."""
    values = [float(value) for value in quaternion]
    if len(values) != 4 or not all(math.isfinite(value) for value in values):
        return False, "orientation_nonfinite"
    norm = math.sqrt(sum(value * value for value in values))
    if norm == 0.0:
        return False, "orientation_all_zero"
    if abs(norm - 1.0) > QUATERNION_UNIT_TOLERANCE:
        return False, "orientation_non_unit"
    return True, None


def pointcloud_layout(msg):
    """Validate PointCloud2 fields/offsets/datatypes/strides/endianness/data length."""
    errors = []
    try:
        width, height = int(msg.width), int(msg.height)
        point_step, row_step = int(msg.point_step), int(msg.row_step)
        bigendian = bool(msg.is_bigendian)
        raw_fields = list(msg.fields)
    except (AttributeError, TypeError, ValueError) as exc:
        return {"valid": False, "errors": ["unreadable_message:" + str(exc)],
                "width": None, "height": None, "point_step": None, "row_step": None,
                "data_bytes": 0, "required_bytes": None, "is_bigendian": None,
                "field_names": []}
    if width <= 0 or height <= 0:
        errors.append("invalid_dimensions")
    if point_step <= 0:
        errors.append("invalid_point_step")
    if row_step < width * point_step:
        errors.append("row_step_smaller_than_points")
    try:
        data = memoryview(msg.data)
        data_bytes = data.nbytes
    except (TypeError, ValueError):
        data = None
        data_bytes = 0
        errors.append("data_not_a_byte_buffer")
    required_bytes = max(0, row_step) * max(0, height)
    if data is not None and data_bytes < required_bytes:
        errors.append("truncated_data")
    fields = {}
    for field in raw_fields:
        name = str(field.name)
        if name in fields:
            errors.append("duplicate_field_" + name)
            continue
        fields[name] = field
    for name in ("x", "y", "z"):
        field = fields.get(name)
        if field is None:
            errors.append("missing_field_" + name)
            continue
        size = 4 if int(field.datatype) == FLOAT32_DATATYPE else 8
        if int(field.datatype) not in (FLOAT32_DATATYPE, FLOAT64_DATATYPE) or int(field.count) != 1:
            errors.append("bad_field_" + name)
        elif int(field.offset) < 0 or int(field.offset) + size > point_step:
            errors.append("field_outside_point_step_" + name)
    timestamp_field = fields.get("timestamp")
    if timestamp_field is None:
        errors.append("missing_field_timestamp")
    elif int(timestamp_field.datatype) != FLOAT64_DATATYPE or int(timestamp_field.count) != 1:
        errors.append("bad_field_timestamp")
    elif int(timestamp_field.offset) < 0 or int(timestamp_field.offset) + 8 > point_step:
        errors.append("field_outside_point_step_timestamp")
    return {"valid": not errors, "errors": errors,
            "width": width, "height": height,
            "point_step": point_step, "row_step": row_step,
            "data_bytes": data_bytes, "required_bytes": required_bytes,
            "is_bigendian": bigendian, "field_names": list(fields)}


def read_point_timestamps(msg):
    """Read the per-point float64 timestamp field at its declared (possibly unaligned) offset."""
    layout = pointcloud_layout(msg)
    if not layout["valid"]:
        raise ValueError("invalid PointCloud2 layout: " + ",".join(layout["errors"]))
    field = next(field for field in msg.fields if str(field.name) == "timestamp")
    try:
        data = memoryview(msg.data)
        dtype = np.dtype(">f8" if layout["is_bigendian"] else "<f8")
        array = np.ndarray((layout["height"], layout["width"]), dtype=dtype, buffer=data,
                           strides=(layout["row_step"], layout["point_step"]),
                           offset=int(field.offset))
        return np.asarray(array, dtype=np.float64).ravel()
    except (TypeError, ValueError) as exc:
        raise ValueError("cannot decode PointCloud2 timestamps: " + str(exc)) from exc


def point_value_summary(total_points, xyz):
    """Summarise decoded xyz points: finite/non-finite and all-zero (invalid-return) counts."""
    total = int(total_points)
    finite = int(len(xyz))
    zero = int(np.count_nonzero(np.all(np.asarray(xyz) == 0.0, axis=1))) if xyz.size else 0
    return {"total_points": total, "nonfinite_points": total - finite,
            "zero_points": zero, "finite_nonzero_points": finite - zero}


def _load_xyz_from_cloud():
    """Reuse human_follow_calibration.xyz_from_cloud instead of copying the decoder."""
    try:
        from calibrate_human_follow import CalibrationError, xyz_from_cloud
        return xyz_from_cloud, CalibrationError
    except ImportError:
        pass
    here = os.path.dirname(os.path.abspath(__file__))
    candidates = (os.path.join(here, "..", "human_follow_calibration"),
                  os.path.join(here, "..", "..", "human_follow_calibration", "scripts"))
    for candidate in candidates:
        candidate = os.path.abspath(candidate)
        if os.path.isfile(os.path.join(candidate, "calibrate_human_follow.py")):
            if candidate not in sys.path:
                sys.path.append(candidate)
    try:
        from calibrate_human_follow import CalibrationError, xyz_from_cloud
        return xyz_from_cloud, CalibrationError
    except ImportError:
        return None, None


class TopicTracker:
    def __init__(self, label, topic, timeout_s, max_forward_jump_s, required):
        self.label = label
        self.topic = topic
        self.timeout_s = float(timeout_s)
        self.max_forward_jump_s = float(max_forward_jump_s)
        self.required = bool(required)
        self.messages = 0
        self.first_receive_s = None
        self.last_receive_s = None
        self.last_stamp = None
        self.stamp_status = "none"
        self.stamp_reason = None
        self.stamp_secs = None
        self.stamp_nsecs = None
        self.last_source_stamp_s = None
        self.frame_id = None

    def note(self, now, stamp, frame_id=None):
        self.messages += 1
        if self.first_receive_s is None:
            self.first_receive_s = float(now)
        self.last_receive_s = float(now)
        if frame_id is not None:
            self.frame_id = frame_id
        status, reason, discontinuity = check_stamp(self.label, self.last_stamp, stamp,
                                                    self.max_forward_jump_s)
        self.stamp_status = status
        self.stamp_reason = reason
        self.stamp_secs, self.stamp_nsecs = raw_stamp(stamp)
        if status == "invalid":
            self.last_source_stamp_s = None
        else:
            self.last_stamp = stamp
            self.last_source_stamp_s = stamp_seconds(stamp)
        return discontinuity

    def block(self, now):
        age = None if self.last_receive_s is None else max(0.0, float(now) - self.last_receive_s)
        if self.messages == 0:
            status = "no_data"
        elif age > self.timeout_s:
            status = "stale"
        else:
            status = "fresh"
        rate = None
        if self.messages >= 2 and self.last_receive_s > self.first_receive_s:
            rate = (self.messages - 1) / (self.last_receive_s - self.first_receive_s)
        return {"topic": self.topic, "required": self.required, "status": status,
                "messages": self.messages, "receive_hz": finite_or_none(rate),
                "last_age_s": finite_or_none(age), "frame_id": self.frame_id,
                "stamp_status": self.stamp_status if self.messages else "none",
                "stamp_reason": self.stamp_reason,
                "stamp_secs": self.stamp_secs,
                "stamp_nsecs": self.stamp_nsecs,
                "source_stamp_s": finite_or_none(self.last_source_stamp_s)}


class HealthMonitor:
    """Pure bookkeeping for the health payload; ROS callbacks only feed this object."""

    def __init__(self, session_id, cloud_topic, imu_topic, device_topic,
                 cloud_timeout_s, imu_timeout_s, device_timeout_s, max_forward_jump_s,
                 expected_cloud_frame=None, units_verified=False, alignment_verified=False,
                 tf_available=False, calibration_status="pending"):
        self._lock = threading.Lock()
        self.session_id = session_id
        self.time_epoch = 0
        self.expected_cloud_frame = expected_cloud_frame
        self.units_verified = bool(units_verified)
        self.alignment_verified = bool(alignment_verified)
        self.tf_available = bool(tf_available)
        self.calibration_status = calibration_status
        self.cloud = TopicTracker("cloud", cloud_topic, cloud_timeout_s,
                                  max_forward_jump_s, required=True)
        self.imu = TopicTracker("imu", imu_topic, imu_timeout_s,
                                max_forward_jump_s, required=False)
        self.device = TopicTracker("device", device_topic, device_timeout_s,
                                   max_forward_jump_s, required=False)
        self.cloud_layout = None
        self.cloud_points = None
        self.cloud_point_stamp = None
        self.cloud_header_equals_first = None
        self.cloud_decode_error = None
        self.imu_measurements_finite = None
        self.imu_acceleration = None
        self.imu_angular_velocity = None
        self.imu_orientation_usable = None
        self.imu_orientation_reason = None
        self.imu_orientation_not_provided = None
        self.imu_covariance_zero = None
        self.device_fields = None

    def note_cloud(self, now, stamp, frame_id=None, layout=None, points=None,
                   point_stamp=None, header_equals_first=None, decode_error=None):
        with self._lock:
            if self.cloud.note(now, stamp, frame_id):
                self.time_epoch += 1
            self.cloud_layout = layout
            self.cloud_points = points
            self.cloud_point_stamp = point_stamp
            self.cloud_header_equals_first = header_equals_first
            self.cloud_decode_error = decode_error

    def note_imu(self, now, stamp, frame_id=None, acceleration=None, angular_velocity=None,
                 orientation=None, orientation_covariance_zero=None,
                 orientation_not_provided=False):
        with self._lock:
            if self.imu.note(now, stamp, frame_id):
                self.time_epoch += 1
            self.imu_acceleration = acceleration
            self.imu_angular_velocity = angular_velocity
            if acceleration is None or angular_velocity is None:
                self.imu_measurements_finite = None
            else:
                values = [float(v) for v in list(acceleration) + list(angular_velocity)]
                self.imu_measurements_finite = all(math.isfinite(v) for v in values)
            if orientation is None:
                self.imu_orientation_usable = None
                self.imu_orientation_reason = None
            elif orientation_not_provided:
                self.imu_orientation_usable = False
                self.imu_orientation_reason = "orientation_not_provided"
            else:
                self.imu_orientation_usable, self.imu_orientation_reason = \
                    quaternion_report(orientation)
            self.imu_orientation_not_provided = bool(orientation_not_provided)
            self.imu_covariance_zero = orientation_covariance_zero

    def note_device(self, now, stamp, frame_id=None, fields=None):
        with self._lock:
            if self.device.note(now, stamp, frame_id):
                self.time_epoch += 1
            self.device_fields = fields

    def _reason_codes(self, cloud_block, imu_block, device_block):
        codes = []

        def add(code):
            if code and code not in codes:
                codes.append(code)

        for tracker, block in ((self.cloud, cloud_block), (self.imu, imu_block),
                               (self.device, device_block)):
            if block["status"] == "no_data":
                add(tracker.label + "_no_data")
            elif block["status"] == "stale":
                add(tracker.label + "_stale")
            add(block["stamp_reason"])
        if self.cloud_layout is not None and not self.cloud_layout["valid"]:
            add("cloud_layout_invalid")
        if self.cloud_decode_error is not None:
            add("cloud_decode_failed")
        if self.cloud_layout is None and self.cloud.messages and self.cloud.stamp_status != "invalid":
            add("cloud_layout_missing")
        if self.cloud_points is not None and self.cloud_points["nonfinite_points"] > 0:
            add("cloud_nonfinite_points")
        if (self.expected_cloud_frame and self.cloud.frame_id
                and self.cloud.frame_id != self.expected_cloud_frame):
            add("cloud_frame_unexpected")
        if self.imu_measurements_finite is False:
            add("imu_measurement_nonfinite")
        if self.imu_orientation_usable is False:
            add("orientation_unusable")
        if not self.units_verified:
            add("imu_units_unverified")
        if not self.alignment_verified:
            add("imu_alignment_unverified")
        if not self.tf_available:
            add("tf_absent")
        if self.calibration_status != "verified":
            add("calibration_pending")
        add("clock_cross_stream_unverified")
        add("host_anchor_unverified")
        if self.device_fields and self.device_fields.get("abnormal_flag") not in (None, 0):
            add("device_abnormal_flag_uninterpreted")
        return codes

    def _observability(self, cloud_block, imu_block, device_block):
        if cloud_block["status"] != "fresh" or cloud_block["stamp_status"] == "invalid":
            return "invalid"
        if self.cloud_layout is None or not self.cloud_layout["valid"]:
            return "invalid"
        if self.cloud_decode_error is not None:
            return "invalid"
        if (self.expected_cloud_frame and self.cloud.frame_id
                and self.cloud.frame_id != self.expected_cloud_frame):
            return "degraded"
        if imu_block["status"] != "fresh" or device_block["status"] != "fresh":
            return "degraded"
        if self.imu_measurements_finite is False:
            return "degraded"
        return "valid"

    def snapshot(self, now):
        with self._lock:
            cloud_block = self.cloud.block(now)
            cloud_block["layout"] = self.cloud_layout
            cloud_block["points"] = self.cloud_points
            cloud_block["point_stamp"] = self.cloud_point_stamp
            cloud_block["header_equals_first_point_stamp"] = self.cloud_header_equals_first
            cloud_block["decode_error"] = self.cloud_decode_error

            imu_block = self.imu.block(now)
            if self.imu_acceleration is None:
                imu_block["raw_acceleration"] = None
            else:
                imu_block["raw_acceleration"] = {
                    "x": finite_or_none(self.imu_acceleration[0]),
                    "y": finite_or_none(self.imu_acceleration[1]),
                    "z": finite_or_none(self.imu_acceleration[2]),
                    "units": "unknown"}
            if self.imu_angular_velocity is None:
                imu_block["raw_angular_velocity"] = None
            else:
                imu_block["raw_angular_velocity"] = {
                    "x": finite_or_none(self.imu_angular_velocity[0]),
                    "y": finite_or_none(self.imu_angular_velocity[1]),
                    "z": finite_or_none(self.imu_angular_velocity[2]),
                    "units": "unknown"}
            imu_block["measurements_finite"] = self.imu_measurements_finite
            imu_block["units_verified"] = self.units_verified
            imu_block["alignment_verified"] = self.alignment_verified
            imu_block["orientation_usable"] = self.imu_orientation_usable
            imu_block["orientation_reason"] = self.imu_orientation_reason
            imu_block["orientation_not_provided"] = self.imu_orientation_not_provided
            imu_block["orientation_covariance_zero"] = self.imu_covariance_zero

            device_block = self.device.block(now)
            fields = self.device_fields or {}
            device_block["device_number"] = fields.get("device_number")
            device_block["trx_temperature"] = finite_or_none(fields.get("trx_temperature"))
            device_block["main_temperature"] = finite_or_none(fields.get("main_temperature"))
            device_block["abnormal_flag"] = fields.get("abnormal_flag")
            device_block["abnormal_flag_semantics"] = "unknown"

            return {
                "schema_version": SCHEMA_VERSION,
                "kind": HEALTH_KIND,
                "session_id": self.session_id,
                "time_epoch": self.time_epoch,
                "time_received_s": finite_or_none(now),
                "source_time_domain": SOURCE_TIME_DOMAIN,
                "normalized_stamp_s": None,
                "observability": self._observability(cloud_block, imu_block, device_block),
                "reason_codes": self._reason_codes(cloud_block, imu_block, device_block),
                "sync": {"cross_stream_same_clock_verified": False,
                         "host_anchor_verified": False},
                "units": {"imu_units_verified": self.units_verified,
                          "imu_alignment_verified": self.alignment_verified},
                "calibration": {"tf_available": self.tf_available, "extrinsics": "unknown",
                                "ground": "unknown", "imu_alignment": "unknown",
                                "geometry_params": self.calibration_status},
                "topics": {"cloud": cloud_block, "imu": imu_block,
                           "device_status": device_block},
            }


def load_config(path):
    try:
        import yaml
    except ImportError as exc:
        raise RuntimeError("PyYAML is required: " + str(exc))
    with open(path, encoding="utf-8") as source:
        return yaml.safe_load(source) or {}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", default=None, help="YAML config; defaults to the package default.yaml")
    parser.add_argument("--session-id", default=None)
    args = parser.parse_args(argv)
    try:
        import rospy
        import rospkg
        from std_msgs.msg import String
        from sensor_msgs.msg import Imu, PointCloud2
        from inno_lidar_msg.msg import DeviceStatus
    except ImportError as exc:
        parser.exit(2, "ROS1 rospy/rospkg/sensor_msgs/std_msgs/inno_lidar_msg required: {}\n".format(exc))
    config_path = args.config
    if config_path is None:
        config_path = os.path.join(rospkg.RosPack().get_path("human_fall_detection"),
                                   "config", "default.yaml")
    config = load_config(config_path)
    topics = config.get("topics", {})
    timeouts = config.get("timeouts_s", {})
    stamp_limits = config.get("stamps", {})
    checks = config.get("checks", {})
    imu_semantics = config.get("imu_semantics", {})
    session_id = args.session_id or "health_" + time.strftime("%Y%m%d_%H%M%S")
    monitor = HealthMonitor(
        session_id=session_id,
        cloud_topic=topics.get("cloud", "/innolidar_points"),
        imu_topic=topics.get("imu", "/inno_imu"),
        device_topic=topics.get("device_status", "/device_status"),
        cloud_timeout_s=float(timeouts.get("cloud_stale", 0.6)),
        imu_timeout_s=float(timeouts.get("imu_stale", 0.3)),
        device_timeout_s=float(timeouts.get("device_stale", 0.6)),
        max_forward_jump_s=float(stamp_limits.get("max_forward_jump_s", 30.0)),
        expected_cloud_frame=checks.get("expected_cloud_frame") or None,
        units_verified=bool(imu_semantics.get("units_verified", False)),
        alignment_verified=bool(imu_semantics.get("alignment_verified", False)))
    xyz_from_cloud, calibration_error = _load_xyz_from_cloud()

    rospy.init_node("human_fall_sensor_health", disable_signals=False)
    publisher = rospy.Publisher(topics.get("health", "/human_fall/health"), String, queue_size=1)

    def on_cloud(msg):
        now = time.monotonic()
        stamp = stamp_pair(msg.header.stamp)
        layout = pointcloud_layout(msg)
        points = None
        point_stamp = None
        header_equals_first = None
        decode_error = None
        if layout["valid"]:
            if xyz_from_cloud is None:
                decode_error = "human_follow_calibration.xyz_from_cloud unavailable"
            else:
                try:
                    timestamps = read_point_timestamps(msg)
                    if timestamps.size:
                        point_stamp = {"first_s": finite_or_none(timestamps[0]),
                                       "last_s": finite_or_none(timestamps[-1]),
                                       "span_s": finite_or_none(timestamps[-1] - timestamps[0])}
                        header_equals_first = (stamp_seconds(stamp) is not None
                                               and stamp_seconds(stamp) == float(timestamps[0]))
                    xyz = xyz_from_cloud(msg, 0.0)
                    points = point_value_summary(layout["width"] * layout["height"], xyz)
                except (ValueError, calibration_error) as exc:
                    decode_error = str(exc)
        monitor.note_cloud(now, stamp, msg.header.frame_id, layout, points,
                           point_stamp, header_equals_first, decode_error)

    def on_imu(msg):
        covariance_zero, not_provided = orientation_covariance_flags(msg.orientation_covariance)
        monitor.note_imu(
            time.monotonic(), stamp_pair(msg.header.stamp), msg.header.frame_id,
            (msg.linear_acceleration.x, msg.linear_acceleration.y, msg.linear_acceleration.z),
            (msg.angular_velocity.x, msg.angular_velocity.y, msg.angular_velocity.z),
            (msg.orientation.x, msg.orientation.y, msg.orientation.z, msg.orientation.w),
            covariance_zero, orientation_not_provided=not_provided)

    def on_device(msg):
        monitor.note_device(time.monotonic(), stamp_pair(msg.header.stamp), msg.header.frame_id,
                            {"device_number": int(msg.device_number),
                             "trx_temperature": float(msg.trx_temperature),
                             "main_temperature": float(msg.main_temperature),
                             "abnormal_flag": int(msg.abnormal_flag)})

    rospy.Subscriber(monitor.cloud.topic, PointCloud2, on_cloud, queue_size=1, buff_size=2 ** 24)
    rospy.Subscriber(monitor.imu.topic, Imu, on_imu, queue_size=64)
    rospy.Subscriber(monitor.device.topic, DeviceStatus, on_device, queue_size=8)
    period = float(config.get("publish_period_s", 0.5))
    rospy.loginfo("Human-fall health: %s + %s + %s -> %s (session %s)",
                  monitor.cloud.topic, monitor.imu.topic, monitor.device.topic,
                  publisher.name, session_id)
    while not rospy.is_shutdown():
        payload = monitor.snapshot(time.monotonic())
        try:
            publisher.publish(String(data=dumps_strict(payload)))
        except ValueError as exc:
            rospy.logerr("Refusing non-finite health payload: %s", exc)
        rospy.sleep(period)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Auxiliary-IMU semantics and data-quality checks (HF-02).

The device IMU is a device-motion / static-gravity reference only; it is not a
human-impact sensor. Six-axis unit verification and orientation validity are
tracked separately. Magnitude clues (gravity-sized acceleration, near-zero
angular rate) are never accepted as scale or axis proof: units/alignment/bias
only become ``verified`` through a named evidence source (vendor protocol or a
controlled known motion/attitude).
"""

import math

from sensor_health import (finite_or_none, orientation_covariance_flags,
                           quaternion_report)

IMU_ROLE = "device_motion_gravity_reference_not_human_impact"
EVIDENCE_SOURCES = ("vendor_protocol", "controlled_motion", "controlled_attitude")
SEMANTIC_FIELDS = ("acceleration_units", "angular_velocity_units",
                   "axis_mapping", "bias")
DEFAULT_GRAVITY_M_S2 = 9.80665
ACCELERATION_UNITS_TO_SI = {"m_s2": 1.0, "g": DEFAULT_GRAVITY_M_S2}
ANGULAR_VELOCITY_UNITS_TO_SI = {"rad_s": 1.0, "deg_s": math.pi / 180.0}


def _validated_bias(value):
    try:
        values = [float(item) for item in value]
    except (TypeError, ValueError):
        raise ValueError("bias must be a sequence of six finite numbers") from None
    if len(values) != 6 or not all(math.isfinite(item) for item in values):
        raise ValueError("bias must be a sequence of six finite numbers")
    return values


# Reference-frame directions used by the supported axis_mapping triad, in a
# right-handed forward/left/up frame (ROS REP-103 style). Only the direction
# names are defined here; the device's actual mounting stays unknown.
REFERENCE_DIRECTIONS = {
    "forward": (1.0, 0.0, 0.0),
    "backward": (-1.0, 0.0, 0.0),
    "left": (0.0, 1.0, 0.0),
    "right": (0.0, -1.0, 0.0),
    "up": (0.0, 0.0, 1.0),
    "down": (0.0, 0.0, -1.0),
}


def _validated_axis_mapping(value):
    """Validate the supported three-axis mapping description.

    Accepted form: ``x_<direction>_y_<direction>_z_<direction>``. It is read
    ``from`` each IMU sensor axis ``x``/``y``/``z`` (listed once, in order)
    ``to`` the direction it points to in the reference frame. The directions
    must be known names, pairwise distinct and form a proper (right-handed)
    rotation, so text such as ``unknown``, missing/duplicate axes, duplicate
    directions and mirrored triads are rejected before any state change. This
    validates the description only; it never guesses the real device axes.
    """
    if not isinstance(value, str):
        raise ValueError("axis_mapping must be a supported triad string")
    tokens = value.split("_")
    if len(tokens) != 6 or tokens[0::2] != ["x", "y", "z"]:
        raise ValueError("axis_mapping must be "
                         "'x_<direction>_y_<direction>_z_<direction>' with each "
                         "sensor axis exactly once")
    directions = tokens[1::2]
    for name in directions:
        if name not in REFERENCE_DIRECTIONS:
            raise ValueError("unsupported axis direction: " + repr(name))
    if len(set(directions)) != 3:
        raise ValueError("axis direction conflict: two sensor axes point the same way")
    first, second, third = (REFERENCE_DIRECTIONS[name] for name in directions)
    cross = (first[1] * second[2] - first[2] * second[1],
             first[2] * second[0] - first[0] * second[2],
             first[0] * second[1] - first[1] * second[0])
    if cross != third:
        raise ValueError("axis_mapping is not a right-handed rotation of x/y/z")
    return value


class ImuSemantics:
    """Per-field verification state for the auxiliary device IMU."""

    def __init__(self):
        self.status = {field: "unknown" for field in SEMANTIC_FIELDS}
        self.values = {}
        self.evidence = []

    def verify(self, field, value, evidence, note=None):
        """Mark one semantic field verified by named evidence.

        The value itself is validated: empty values, unsupported unit names,
        invalid axis-mapping descriptions and wrong-sized/non-finite bias
        vectors are rejected before any state mutation, so neither an empty nor
        an arbitrary ``verify`` call can enable motion classification.
        """
        if field not in SEMANTIC_FIELDS:
            raise ValueError("unknown IMU semantic field: " + str(field))
        if evidence not in EVIDENCE_SOURCES:
            raise ValueError(
                "unsupported evidence {!r}: magnitude hints (gravity-sized "
                "acceleration, near-zero rate) are not scale proof".format(evidence))
        if field == "acceleration_units":
            if not isinstance(value, str) or value not in ACCELERATION_UNITS_TO_SI:
                raise ValueError("unsupported acceleration units: " + repr(value))
        elif field == "angular_velocity_units":
            if not isinstance(value, str) or value not in ANGULAR_VELOCITY_UNITS_TO_SI:
                raise ValueError("unsupported angular velocity units: " + repr(value))
        elif field == "axis_mapping":
            value = _validated_axis_mapping(value)
        elif field == "bias":
            value = _validated_bias(value)
        self.status[field] = "verified"
        self.values[field] = value
        self.evidence.append({"field": field, "value": value, "evidence": evidence,
                              "note": note})
        return dict(self.report())

    @property
    def units_verified(self):
        return (self.status["acceleration_units"] == "verified"
                and self.status["angular_velocity_units"] == "verified")

    @property
    def alignment_verified(self):
        return self.status["axis_mapping"] == "verified"

    def report(self):
        return {"role": IMU_ROLE,
                "acceleration_units": self.status["acceleration_units"],
                "angular_velocity_units": self.status["angular_velocity_units"],
                "axis_mapping": self.status["axis_mapping"],
                "bias": self.status["bias"],
                "values": dict(self.values),
                "units_verified": self.units_verified,
                "alignment_verified": self.alignment_verified,
                "evidence": [dict(item) for item in self.evidence]}


def six_axis_report(acceleration, angular_velocity):
    """Finiteness of the six-axis measurement, kept separate from orientation.

    A usable six-axis sample is exactly three finite acceleration values and
    exactly three finite angular-velocity values; missing/extra axes or
    unreadable values are reported invalid instead of being treated as finite.
    """
    if acceleration is None or angular_velocity is None:
        return {"finite": None, "reason": None}
    try:
        accel = [float(value) for value in acceleration]
        rate = [float(value) for value in angular_velocity]
    except (TypeError, ValueError):
        return {"finite": False, "reason": "imu_measurement_malformed"}
    if len(accel) != 3 or len(rate) != 3:
        return {"finite": False, "reason": "imu_axis_count_invalid"}
    finite = all(math.isfinite(value) for value in accel + rate)
    return {"finite": finite,
            "reason": None if finite else "imu_measurement_nonfinite"}


def orientation_report(quaternion, covariance):
    """Orientation usability, reusing the frozen HF-01 rules.

    ``covariance[0] == -1`` (not provided) and all-zero/non-unit/non-finite
    quaternions are unusable; no valid quaternion is ever fabricated.
    """
    covariance_zero, not_provided = orientation_covariance_flags(covariance)
    if not_provided:
        usable, reason = False, "orientation_not_provided"
    elif quaternion is None:
        usable, reason = None, None
    else:
        usable, reason = quaternion_report(quaternion)
    return {"usable": usable, "reason": reason,
            "not_provided": bool(not_provided),
            "covariance_zero": bool(covariance_zero)}


def device_motion_status(acceleration, angular_velocity, semantics,
                         gravity_m_s2=DEFAULT_GRAVITY_M_S2,
                         accel_tolerance_m_s2=0.25,
                         rate_tolerance_rad_s=0.03):
    """Static/moving status of the device, only once units+axes are verified.

    Raw values are converted from the verified units (``m_s2``/``g`` and
    ``rad_s``/``deg_s``) to SI before the SI thresholds are compared; unknown
    or unsupported units keep the verdict ``unknown`` instead of silently
    assuming SI. Thresholds are the physical tuning knobs for the board
    installation. This is a device-motion hint only: bias/alignment and the
    static-background ground/background conditions stay separate, and this
    verdict alone never enables fusion.
    """
    if not semantics.units_verified:
        return {"status": "unknown", "reason": "imu_units_unverified",
                "scope": IMU_ROLE}
    if not semantics.alignment_verified:
        return {"status": "unknown", "reason": "imu_alignment_unverified",
                "scope": IMU_ROLE}
    accel_scale = ACCELERATION_UNITS_TO_SI.get(semantics.values.get("acceleration_units"))
    rate_scale = ANGULAR_VELOCITY_UNITS_TO_SI.get(
        semantics.values.get("angular_velocity_units"))
    if accel_scale is None or rate_scale is None:
        return {"status": "unknown", "reason": "imu_units_unverified",
                "scope": IMU_ROLE}
    report = six_axis_report(acceleration, angular_velocity)
    if report["finite"] is not True:
        return {"status": "unknown", "reason": report["reason"] or "imu_measurement_missing",
                "scope": IMU_ROLE}
    magnitude = math.sqrt(sum((float(value) * accel_scale) ** 2
                              for value in acceleration))
    max_rate = max(abs(float(value)) * rate_scale for value in angular_velocity)
    gravity_residual = abs(magnitude - float(gravity_m_s2))
    if gravity_residual <= float(accel_tolerance_m_s2) and max_rate <= float(rate_tolerance_rad_s):
        status = "static"
    else:
        status = "moving"
    return {"status": status, "reason": None, "scope": IMU_ROLE,
            "gravity_residual_m_s2": gravity_residual,
            "max_angular_rate": finite_or_none(max_rate),
            "comparison_units": "m_s2/rad_s"}


def static_background_usable(ground_valid, background_residual_ok, device_motion):
    """Gate the static-background scheme on ground, residual and device motion.

    A missing IMU motion verdict is not a pass: the IMU alone cannot prove the
    device did not translate, so unknown motion keeps the scheme unusable and
    asks for a fresh on-site initialisation along with the other failures.
    """
    reasons = []
    if ground_valid is not True:
        reasons.append("ground_invalid")
    if background_residual_ok is not True:
        reasons.append("background_residual_invalid")
    if device_motion != "static":
        reasons.append("device_motion_" + str(device_motion))
    usable = not reasons
    return {"usable": usable, "reinit_required": not usable, "reasons": reasons}

